#!/usr/bin/env python3
"""Render the package manifests for one release from its checksums.

    python3 dist/render.py --version 0.1.0 --sums sha256sums.txt \
        --repo NickStrain/Myrn- --out rendered

Writes, under --out:
    homebrew/myrn.rb                   formula for the tap (Formula/myrn.rb)
    scoop/myrn.json                    Scoop manifest (also a release asset)
    winget/<id>.yaml, .installer.yaml, .locale.en-US.yaml   winget manifests
    npm/                               the npm wrapper package, versioned

Archives are named myrn-<target>.tar.gz (Linux, macOS) and myrn-<target>.zip
(Windows), as the release workflow builds them. Standard library only.
"""

import argparse
import json
import shutil
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent

# (archive target, Homebrew os, Homebrew cpu)
UNIX = [
    ("aarch64-apple-darwin", "macos", "arm"),
    ("x86_64-apple-darwin", "macos", "intel"),
    ("aarch64-unknown-linux-musl", "linux", "arm"),
    ("x86_64-unknown-linux-musl", "linux", "intel"),
]
# (archive target, Scoop arch, winget arch)
WINDOWS = [
    ("x86_64-pc-windows-msvc", "64bit", "x64"),
    ("aarch64-pc-windows-msvc", "arm64", "arm64"),
]
DESCRIPTION = "Persistent project memory for AI coding agents"
WINGET_ID = "NickStrain.Myrn"


def read_sums(path):
    sums = {}
    for line in Path(path).read_text().splitlines():
        parts = line.split()
        if len(parts) == 2:
            sums[parts[1].lstrip("*")] = parts[0]
    return sums


def need(sums, name):
    if name not in sums:
        sys.exit(f"render.py: {name} is missing from the checksums")
    return sums[name]


def homebrew(version, sums, base):
    blocks = {}
    for target, os_, cpu in UNIX:
        name = f"myrn-{target}.tar.gz"
        blocks.setdefault(os_, []).append(
            f"    on_{cpu} do\n"
            f'      url "{base}/{name}"\n'
            f'      sha256 "{need(sums, name)}"\n'
            f"    end\n"
        )
    body = "".join(
        f"  on_{os_} do\n{''.join(parts)}  end\n\n" for os_, parts in blocks.items()
    )
    return (
        "# Generated by dist/render.py for the release; do not edit by hand.\n"
        "class Myrn < Formula\n"
        f'  desc "{DESCRIPTION}"\n'
        f'  homepage "https://github.com/{REPO}"\n'
        f'  version "{version}"\n'
        '  license "Apache-2.0"\n\n'
        f"{body}"
        "  def install\n"
        '    bin.install "myrn"\n'
        "  end\n\n"
        "  test do\n"
        '    assert_match version.to_s, shell_output("#{bin}/myrn --version")\n'
        "  end\n"
        "end\n"
    )


def scoop(version, sums, base):
    arch = {}
    for target, scoop_arch, _ in WINDOWS:
        name = f"myrn-{target}.zip"
        arch[scoop_arch] = {"url": f"{base}/{name}", "hash": need(sums, name)}
    return {
        "version": version,
        "description": DESCRIPTION,
        "homepage": f"https://github.com/{REPO}",
        "license": "Apache-2.0",
        "architecture": arch,
        "bin": "myrn.exe",
        "checkver": {"github": f"https://github.com/{REPO}"},
        "autoupdate": {
            "architecture": {
                scoop_arch: {
                    "url": f"https://github.com/{REPO}/releases/download/v$version/myrn-{target}.zip"
                }
                for target, scoop_arch, _ in WINDOWS
            },
            "hash": {"url": "$baseurl/sha256sums.txt", "regex": "([a-fA-F0-9]{64})\\s+$basename"},
        },
    }


def winget(version, sums, base):
    head = (
        "# Generated by dist/render.py; submit to microsoft/winget-pkgs (see docs/releasing.md).\n"
        f"PackageIdentifier: {WINGET_ID}\n"
        f"PackageVersion: {version}\n"
    )
    installers = "".join(
        f"  - Architecture: {wa}\n"
        f"    InstallerUrl: {base}/myrn-{target}.zip\n"
        f"    InstallerSha256: {need(sums, f'myrn-{target}.zip').upper()}\n"
        for target, _, wa in WINDOWS
    )
    return {
        f"{WINGET_ID}.yaml": head
        + "DefaultLocale: en-US\nManifestType: version\nManifestVersion: 1.6.0\n",
        f"{WINGET_ID}.installer.yaml": head
        + "InstallerType: zip\n"
        "NestedInstallerType: portable\n"
        "NestedInstallerFiles:\n"
        "  - RelativeFilePath: myrn.exe\n"
        "    PortableCommandAlias: myrn\n"
        "Installers:\n"
        + installers
        + "ManifestType: installer\nManifestVersion: 1.6.0\n",
        f"{WINGET_ID}.locale.en-US.yaml": head
        + "PackageLocale: en-US\n"
        "Publisher: NickStrain\n"
        "PackageName: myrn\n"
        "License: Apache-2.0\n"
        f"ShortDescription: {DESCRIPTION}\n"
        f"PackageUrl: https://github.com/{REPO}\n"
        "Moniker: myrn\n"
        "Tags:\n  - ai\n  - agents\n  - mcp\n  - developer-tools\n"
        "ManifestType: defaultLocale\nManifestVersion: 1.6.0\n",
    }


def npm(version, out):
    src = HERE / "npm"
    dst = out / "npm"
    if dst.exists():
        shutil.rmtree(dst)
    shutil.copytree(src, dst, ignore=shutil.ignore_patterns(".gitkeep", "node_modules", "test", "bin-cache"))
    pkg_path = dst / "package.json"
    pkg = json.loads(pkg_path.read_text())
    pkg["version"] = version
    pkg["repository"] = {"type": "git", "url": f"git+https://github.com/{REPO}.git"}
    pkg_path.write_text(json.dumps(pkg, indent=2) + "\n")
    for doc in ("README.md", "LICENSE"):
        p = HERE.parent / doc
        if p.exists():
            shutil.copy(p, dst / doc)


def main():
    global REPO
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--version", required=True)
    ap.add_argument("--sums", required=True)
    ap.add_argument("--repo", default="NickStrain/Myrn-")
    ap.add_argument("--out", required=True)
    a = ap.parse_args()
    REPO = a.repo
    version = a.version.lstrip("v")
    sums = read_sums(a.sums)
    base = f"https://github.com/{REPO}/releases/download/v{version}"
    out = Path(a.out)
    (out / "homebrew").mkdir(parents=True, exist_ok=True)
    (out / "scoop").mkdir(parents=True, exist_ok=True)
    (out / "winget").mkdir(parents=True, exist_ok=True)
    (out / "homebrew" / "myrn.rb").write_text(homebrew(version, sums, base))
    (out / "scoop" / "myrn.json").write_text(json.dumps(scoop(version, sums, base), indent=2) + "\n")
    for name, text in winget(version, sums, base).items():
        (out / "winget" / name).write_text(text)
    npm(version, out)
    print(f"rendered manifests for {version} into {out}")


REPO = "NickStrain/Myrn-"

if __name__ == "__main__":
    main()
